// Typical workflow: docker run does all of this in one command
// But you can split it into steps for debugging or advanced scenarios

// Step 1: Pull the image from Docker Hub (optional - run does this automatically)
$ docker pull postgres:15-alpine
// Output: Pulling layers, verifying checksums, extracting to local storage

// Step 2: Create a container from the image (sets up config, doesn't start it)
$ docker create --name mydb \
    -e POSTGRES_PASSWORD=secret \
    -v postgres-data:/var/lib/postgresql/data \
    -p 5432:5432 \
    postgres:15-alpine
// Output: <container-id>

// Step 3: Start the container (launches the postgres process)
$ docker start mydb

// Step 4: Check it's running
$ docker ps
// Shows CONTAINER ID, IMAGE, COMMAND, STATUS, PORTS

// The shortcut that combines create + start:
$ docker run -d --name mydb \
    -e POSTGRES_PASSWORD=secret \
    -v postgres-data:/var/lib/postgresql/data \
    -p 5432:5432 \
    postgres:15-alpine
